import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const sessionWith = (content: string): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
});

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const turnOutcome = async (reason: unknown) => {
  const callOrder: string[] = [];
  let seenError: Error | undefined;
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      callOrder.push('onError');
      seenError = error;
    },
    afterSession: async () => {
      callOrder.push('afterSession');
    },
  };

  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});
  const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
    value => ({rejected: false, reason: value as unknown}),
    (thrown: unknown) => ({rejected: true, reason: thrown})
  );

  return {
    outcome,
    callOrder,
    isError: seenError instanceof Error,
    message: seenError?.message,
  };
};

describe('ChatOrchestrator onError on non-Error rejections', () => {
  it('calls onError with an Error carrying the thrown string and runs afterSession while rethrowing', async () => {
    const result = await turnOutcome('string boom');

    expect(result).toEqual({
      outcome: {rejected: true, reason: 'string boom'},
      callOrder: ['onError', 'afterSession'],
      isError: true,
      message: 'string boom',
    });
  });

  it('calls onError with an Error carrying a readable message when the stream rejects with a plain object', async () => {
    const reason = {code: 503, detail: 'upstream down'};

    const result = await turnOutcome(reason);

    expect({
      outcome: result.outcome,
      callOrder: result.callOrder,
      isError: result.isError,
      hasMessage: typeof result.message === 'string' && result.message.length > 0,
    }).toEqual({
      outcome: {rejected: true, reason},
      callOrder: ['onError', 'afterSession'],
      isError: true,
      hasMessage: true,
    });
  });
});
# Tool Responses

| Field  | Value |
| ------ | ----- |
| Issue  | n/a   |
| Status | Draft |

By default, a tool executor returns a plain string that feeds back into the AI conversation. The client never sees the result -- it only sees the tool invocation (name and input parameters). This is fine for most tools, but sometimes a tool knows exactly what to show the user and does not need the AI to rephrase it.

The `ToolResponse` interface gives tools two additional capabilities:

1. **Client messages** -- send one or more WebSocket messages directly to the client
2. **Suppress the AI response** -- keep the model's reply in conversation context but hide it from the client

These are opt-in. Tools that return a plain string continue to work exactly as before.

## The ToolResponse Interface

<!-- doc-block: src/orchestration/tools/registry.ts#ToolResponse -->

```typescript
interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}
```

| Field                       | Purpose                                                                                                                               |
| --------------------------- | ------------------------------------------------------------------------------------------------------------------------------------- |
| `result`                    | The string the AI model sees -- identical to what a plain-string executor returns                                                     |
| `clientMessages`            | Optional array of `OutgoingMessage` values sent directly to the client via WebSocket                                                  |
| `suppressAssistantResponse` | When `true`, the AI's next text response still accumulates in `session.entries` for context continuity, but is not sent to the client |

A `ToolExecutor` can return either a plain `string` or a `ToolResponse`:

<!-- doc-block: src/orchestration/tools/registry.ts#ToolExecutor -->

```typescript
type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;
```

`context` carries the session the call belongs to -- `userId`, `sessionId`, `workspaceId`, and the `authHeaders` forwarded from the WebSocket upgrade, so a tool can proxy the caller's credentials upstream.

The registry normalizes both forms internally via `normalizeToolResponse()`, so downstream code always sees a `ToolResponse`.

## When to Use This

**Client messages** make sense when the tool result is self-explanatory and the AI does not need to interpret it for the user. A unit conversion, a status update, a formatted data table -- these are cases where the tool knows the best presentation and the AI would just parrot the same information.

**Suppression** pairs naturally with client messages. If the tool already sent the answer to the client, the AI's follow-up ("The conversion result is 160.93 km") adds no value. Suppression hides that echo while keeping it in the conversation so the AI remembers the context for follow-up questions.

Use plain string returns (the default) when the AI needs to interpret or summarize the tool result for the user. Database lookups and search results are good examples -- the raw data benefits from the AI explaining it in context.

## Data Flow

```
Plain string:    executor returns "data"
                   -> normalizeToolResponse wraps to {result: "data"}
                   -> orchestrator feeds result to AI
                   -> AI responds, client sees the response

With client messages:
                 executor returns {result, clientMessages, suppressAssistantResponse}
                   -> orchestrator extracts .result for AI (unchanged)
                   -> orchestrator yields tool_result chunk carrying clientMessages
                   -> if suppress, orchestrator yields suppress_output chunk
                   -> messageHandler sends clientMessages to client
                   -> messageHandler blanks pre-tool assistant entries (entry_upsert with empty content)
                   -> messageHandler skips WebSocket sends for suppressed entries
                   -> messageHandler sends entry_skip for each new suppressed entry
                   -> suppressed entries still accumulate in session.entries
                   -> client adjusts incoming indices using tracked skip list
```

The key insight: suppressed entries are invisible to the client but visible to the AI. The conversation context stays intact, so the model can reference previous tool results even when the user did not see the AI's commentary on them.

## Example: Unit Converter

The `convert_units` tool demonstrates all three features: client messages, suppression, and index assignment. A conversion like "100 miles to kilometers" has a definitive answer -- the AI does not need to elaborate.

<!-- doc-block: none -- a simplified tool, marked simplified in its own first line -->

```typescript
// src/orchestration/tools/unitConverterTool.ts (simplified)

export const executeUnitConverter: ToolExecutor = async input => {
  const value = input.value as number;
  const fromUnit = (input.from_unit as string) || '';
  const toUnit = (input.to_unit as string) || '';

  const result = convert(value, fromUnit, toUnit);

  if (!result) {
    // Error case: return plain string so AI can explain the problem
    return JSON.stringify({error: `Cannot convert from "${fromUnit}" to "${toUnit}".`});
  }

  return {
    result: JSON.stringify({value, fromUnit, toUnit, converted: result.converted, formatted: result.formatted}),
    clientMessages: [
      {
        type: 'entry_upsert',
        index: 0,
        entry: {role: 'assistant', content: result.formatted, timestamp: new Date().toISOString(), isStreaming: false},
      },
    ],
    suppressAssistantResponse: true,
  };
};
```

Notice three things:

1. On success, the executor returns a `clientMessages` array with an `entry_upsert` containing the formatted result. The client receives this as an assistant entry. The `index` is set to `0` -- the orchestrator replaces it with the correct session index (see "Index assignment" below).

2. `suppressAssistantResponse: true` hides the AI's follow-up. The AI still receives the result string (so it has context for follow-ups), but the client does not see the AI echoing "100 miles equals 160.93 km."

3. On error, the executor returns a plain string. This lets the AI explain what went wrong in its own words -- "I could not convert miles to knots because they measure different things."

# Config-Installed Orchestrator Hooks

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#36 |
| Status | Shipped              |

`OrchestratorHooks` is the engine's only lifecycle seam, and `HalEngineConfig.orchestrator.hooks` is the supported way to install it: `createHalEngine` forwards the set to `createChatOrchestrator`, so a hook a deployer passes through the factory reaches the running orchestrator rather than sitting unread on the config object. This spec pins that forwarding and the measured semantics the seam already carries, so the hook-based features that follow in this epic — transparency disclosure, audit and usage recording, human oversight, provider failover — specify against real behaviour rather than against what the hook names suggest.

## Installing hooks through config

- A hook passed through `orchestrator.hooks` is forwarded to the orchestrator and fires ([validated by: forwards an orchestrator hook, so one passed through the config actually fires](../../src/config.test.ts#L19)).
- An engine built with no `orchestrator` key at all still processes a message, so the field is optional in fact and not only in the type ([validated by: processes a message when the config declares no orchestrator key at all](../../src/config.test.ts#L95)).
- A `beforeModelResponse` hook installed through config is handed the base system prompt built from `prompt`, proving the hook reaches the orchestrator and is wired into the prompt pipeline rather than only being stored on the config ([validated by: hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it](../../src/config.test.ts#L129)).
- The value the hook returns then replaces the system prompt the provider receives; this is exercised at the orchestrator layer because `HalEngineConfig.provider` takes a `ProviderConfig` and offers no seam to inject a recording provider through config ([validated by: replaces system prompt with returned value](../../src/orchestration/chatOrchestrator.test.ts#L233)).
- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L153)).
- A `beforeSession` that throws reaches the caller as a rejection, and also runs `onError` with the thrown error and then `afterSession`, because the call sits inside the same `try`/`finally` as the rest of the turn. An `afterSession` hook called under this condition can infer the session never advanced past `beforeSession`: no user-input hooks ran, no model response was generated, and no tool rounds were started — a cleanup hook that allocates in `beforeSession` and frees in `afterSession` will therefore always see the allocation and the release on the same error path ([validated by: runs onError then afterSession when it throws, and still rejects to the caller](../../src/orchestration/chatOrchestrator.test.ts#L128)).
- `afterModelResponse` is called once per user message after the round loop exits and is passed `totalUsage` — the sum of the usage every provider call in the turn reported, not the last round alone ([validated by: sums the usage of every round, not only the last](../../src/orchestration/chatOrchestrator.test.ts#L593)).
- Any rejection inside the turn calls `onError` with an `Error` — passed through when the thrown value is already an `Error`, or wrapped with a readable `message` when a string or object is thrown — and then runs `afterSession` while still propagating the rejection to the caller ([validated by: wraps a non-Error rejection with its original cause and rethrows it unchanged](../../src/orchestration/chatOrchestrator.test.ts#L290), [validated by: calls onError with an Error carrying the thrown string and runs afterSession while rethrowing](../../src/orchestration/onErrorNonError.acceptance.test.ts#L53), [validated by: calls onError with an Error carrying a readable message when the stream rejects with a plain object](../../src/orchestration/onErrorNonError.acceptance.test.ts#L64)).

## Engine startup

- The engine's `start()` method rejects the returned promise when it cannot bind the configured port, rather than emitting an unhandled error event that would take the process down ([validated by: rejects instead of taking the process down with an unhandled error event](../../src/config.test.ts#L195)).
